(()=>{const e=document.getElementById("results"),i=NB.loadResult(),n='\n    <div class="res-actions">\n      <a href="scan.html?mode=camera" class="btn btn-dark"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;margin-right:6px"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"></path><circle cx="12" cy="13" r="4"></circle></svg>Scan Another Food</a>\n      <a href="scan.html?mode=upload" class="btn btn-light"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;margin-right:6px"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="17 8 12 3 7 8"></polyline><line x1="12" y1="3" x2="12" y2="15"></line></svg>Upload Another Photo</a>\n      <a href="progress.html" class="btn btn-light"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;margin-right:6px"><rect x="3" y="4" width="18" height="18" rx="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line x1="3" y1="10" x2="21" y2="10"></line></svg>My Progress</a>\n      <a href="index.html" class="btn btn-light"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;margin-right:6px"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"></path><polyline points="9 22 9 12 15 12 15 22"></polyline></svg>Return Home</a>\n    </div>';if(!i)return void(e.innerHTML=`<div class="empty-state"><div class="big"><svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="var(--muted)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20"></path><path d="M2 12h20"></path></svg></div><h2>No scan yet</h2>\n      <p style="color:var(--muted);margin:8px 0 10px">Scan or upload a food photo to see its calories and nutrients.</p>${n}</div>`);const t=e=>Math.round(Number(e)||0),a=i.macros||{},r=t(i.calories),s=NB.getGoal(),l=NB.dayTotals(i.day).calories,o=Math.max(1,Math.min(10,t(i.healthScore)||5)),c=o>=8?"var(--green)":o>=5?"#eab308":"#ef4444",d=4*t(a.protein),h=4*t(a.carbs),p=9*t(a.fat),g=d+h+p||1,v=e=>Math.round(e/g*100),y=e=>(e||[]).map(e=>`<li>${NB.esc(e)}</li>`).join(""),m=i.pros?.length?i.pros:["Provides energy and essential nutrients."],x=i.cons?.length?i.cons:["Enjoy in moderation as part of a balanced diet."];e.innerHTML=`\n    <div class="res-top">\n      <div>\n        <span class="badge green"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-1px;margin-right:4px"><polyline points="20 6 9 17 4 12"></polyline></svg>Scan complete · logged to Day ${i.day}</span>\n        <h1 style="margin-top:12px">${NB.esc(i.foodName||"Your food")}</h1>\n        <p>${NB.esc(i.description||"")}</p>\n      </div>\n      <a href="scan.html?mode=camera" class="btn btn-dark btn-sm"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-2px;margin-right:4px"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"></path><circle cx="12" cy="13" r="4"></circle></svg>Scan another</a>\n    </div>\n\n    <div class="res-grid">\n      <div class="panel res-image">\n        <img src="${i.image}" alt="${NB.esc(i.foodName)}" />\n        <div class="res-meta">\n          ${i.servingSize?`<span class="badge"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:4px"><circle cx="12" cy="12" r="9"></circle><path d="M12 7v5l3 3"></path></svg>${NB.esc(i.servingSize)}</span>`:""}\n          ${i.confidence?`<span class="badge green"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:4px"><circle cx="12" cy="12" r="10"></circle><circle cx="12" cy="12" r="6"></circle><circle cx="12" cy="12" r="2"></circle></svg>${t(i.confidence)}% confidence</span>`:""}\n          ${i.model?`<span class="badge"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-1px;margin-right:4px"><rect x="4" y="4" width="16" height="16" rx="2"></rect><rect x="9" y="9" width="6" height="6"></rect></svg>${NB.esc(i.model.split("/").pop())}</span>`:""}\n        </div>\n      </div>\n      <div>\n        <div class="panel res-cal">\n          <div class="ring-wrap">${NB.ring({size:210,stroke:16,id:"calRing",over:r>s})}\n            <div class="ring-center">\n              <div class="ring-metric">\n                <div id="calNum" class="cal-number">${Math.round(r).toLocaleString()}</div>\n                <div class="cal-unit">calories</div>\n              </div>\n            </div>\n          </div>\n          <div>\n            <h2>Total Calories</h2>\n            <p>This is <strong>${Math.round(r/s*100)}%</strong> of your ${s} kcal daily goal. Day ${i.day} total so far: <strong>${l} kcal</strong>.</p>\n            <span class="badge dark"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${c};margin-right:6px"></span>Health score ${o}/10</span>\n          </div>\n        </div>\n        <div class="macro-cards">\n          ${[{key:"protein",label:"Protein",color:"var(--protein)",dv:50},{key:"carbs",label:"Carbs",color:"var(--carbs)",dv:275},{key:"fat",label:"Fat",color:"var(--fat)",dv:78},{key:"fiber",label:"Fiber",color:"var(--fiber)",dv:28},{key:"sugar",label:"Sugar",color:"var(--sugar)",dv:50}].map(e=>`<div class="macro">\n            <div class="val" style="color:${e.color}">${t(a[e.key])}g</div>\n            <div class="lbl">${e.label}</div>\n            <div class="bar"><i style="background:${e.color}" data-w="${Math.min(100,t(a[e.key])/e.dv*100)}"></i></div></div>`).join("")}\n        </div>\n      </div>\n    </div>\n\n    <div class="grid2">\n      <div class="pc pro"><h3><span class="dot">✓</span>Advantages</h3><ul class="pc-list">${y(m)}</ul></div>\n      <div class="pc con"><h3><span class="dot">!</span>Disadvantages</h3><ul class="pc-list">${y(x)}</ul></div>\n    </div>\n\n    <div class="grid2">\n      <div class="panel">\n        <h3><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-2px;margin-right:6px"><path d="M10 2v7.31"></path><path d="M14 9.3V2"></path><path d="M8.5 2h7"></path><path d="M14 9.3a6.5 6.5 0 1 1-4 0"></path><path d="M5.52 16h12.96"></path></svg>Nutrients &amp; minerals</h3>\n        <div class="micro-grid">\n          ${(i.micros||[]).map(e=>`<div class="micro"><span>${NB.esc(e.name)}</span><strong>${t(e.amount)} ${NB.esc(e.unit||"")}</strong></div>`).join("")||'<p style="color:var(--muted)">No micronutrient data available.</p>'}\n        </div>\n        <h3 style="margin-top:22px"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-2px;margin-right:6px"><path d="M21.21 15.89A10 10 0 1 1 8 2.83"></path><path d="M22 12A10 10 0 0 0 12 2v10z"></path></svg>Calorie breakdown</h3>\n        <div class="macro-split">\n          <i style="background:var(--protein);width:${v(d)}%"></i><i style="background:var(--carbs);width:${v(h)}%"></i><i style="background:var(--fat);width:${v(p)}%"></i>\n        </div>\n        <div class="legend"><span style="--c:var(--protein)">Protein ${v(d)}%</span><span style="--c:var(--carbs)">Carbs ${v(h)}%</span><span style="--c:var(--fat)">Fat ${v(p)}%</span></div>\n      </div>\n      <div class="panel">\n        <h3><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-2px;margin-right:6px"><path d="M18 8h1a4 4 0 0 1 0 8h-1"></path><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"></path><line x1="6" y1="1" x2="6" y2="4"></line><line x1="10" y1="1" x2="10" y2="4"></line><line x1="14" y1="1" x2="14" y2="4"></line></svg>Detected items</h3>\n        <ul class="items-list">\n          ${(i.items||[]).map(e=>`<li><span>${NB.esc(e.name)}</span><strong>${t(e.calories)} kcal</strong></li>`).join("")||`<li><span>${NB.esc(i.foodName)}</span><strong>${r} kcal</strong></li>`}\n        </ul>\n        ${(i.tips||[]).length?`<h3 style="margin-top:22px"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="vertical-align:-2px;margin-right:6px"><path d="M9 18h6M10 22h4M15 9a3 3 0 1 0-6 0c0 1.5 1 2.5 1.5 3.5.5 1 .5 1.5.5 1.5h2s0-.5.5-1.5c.5-1 1.5-2 1.5-3.5z"></path></svg>Healthy tips</h3><ul class="tips-list">${y(i.tips)}</ul>`:""}\n      </div>\n    </div>\n\n    <p class="logged-note"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="var(--green)" stroke-width="2" style="vertical-align:-2px;margin-right:6px"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"></polyline><polyline points="17 6 23 6 23 12"></polyline></svg>Added to your Day ${i.day} calorie intake</p>\n    ${n}`,NB.setRing(document.getElementById("calRing"),r/s),setTimeout(()=>document.querySelectorAll(".bar i").forEach(e=>e.style.width=e.dataset.w+"%"),150)})();